 // SSLChecker checks SSL/TLS certificates
@@ -37,12 +39,16 @@ func (s *SSLChecker) Check(ctx context.Context, component config.ComponentConfig

 	// Measure connection time
 	start := time.Now()
-	certs, err := FetchCertificateChain(component.Target, s.timeout)
+	certs, err := FetchCertificateChainContext(ctx, component.Target, s.timeout)
 	result.ResponseTime = time.Since(start)

 	if err != nil {
 		result.Status = StatusDown
 		result.Error = err.Error()
+		var proxyErr *netproxy.Error
+		if errors.As(err, &proxyErr) {
+			result.ErrorStage = StageProxy
+		}
 		return result
 	}
 	if len(certs) == 0 {
diff --git i/internal/status/tls_dial.go w/internal/status/tls_dial.go
index 56bbb609..6ab6c1c2 100644
--- i/internal/status/tls_dial.go
+++ w/internal/status/tls_dial.go
@@ -1,13 +1,24 @@
 package status

 import (
+	"context"
 	"crypto/tls"
 	"crypto/x509"
 	"net"
 	"strings"
 	"time"
+
+	"github.com/anthnel/devdesk/internal/netproxy"
 )

+// certDialer opens the connection the SSL check reads a chain from. The zero
+// value follows the proxy environment variables; tests swap it.
+var certDialer = netproxy.Dialer{}
+
+// certRootCAs is the pool the SSL check verifies against; nil means the system
+// roots. Tests set it so a self-signed server can pass verification.
+var certRootCAs *x509.CertPool
+
 // hostWithPort defaults a bare target to :443, the assumption SSLChecker and
 // the certificate viewer both make about an unqualified target.
 func hostWithPort(target string) string {
@@ -24,8 +35,26 @@ func hostWithPort(target string) string {
 // every refresh, pulled out so the document viewer can ask the same question
 // again without a second copy of the dial.
 func FetchCertificateChain(target string, timeout time.Duration) ([]*x509.Certificate, error) {
-	dialer := &net.Dialer{Timeout: timeout}
-	conn, err := tls.DialWithDialer(dialer, "tcp", hostWithPort(target), &tls.Config{
+	return FetchCertificateChainContext(context.Background(), target, timeout)
+}
+
+// FetchCertificateChainContext is FetchCertificateChain bounded by ctx as well
+// as by timeout. The connection follows the proxy environment variables like
+// the HTTPS monitor does; a failure of the proxy step is a *netproxy.Error,
+// while a certificate or handshake failure of the target is returned as it
+// would be without a proxy. The timeout also covers a proxy that never answers.
+func FetchCertificateChainContext(ctx context.Context, target string, timeout time.Duration) ([]*x509.Certificate, error) {
+	hostport := hostWithPort(target)
+	host, _, err := net.SplitHostPort(hostport)
+	if err != nil {
+		return nil, err
+	}
+	ctx, cancel := context.WithTimeout(ctx, timeout)
+	defer cancel()
+
+	conn, err := certDialer.DialTLS(ctx, hostport, &tls.Config{
+		ServerName:         host,
+		RootCAs:            certRootCAs,
 		InsecureSkipVerify: false, // Validate certificates
 	})
 	if err != nil {
diff --git i/internal/status/types.go w/internal/status/types.go
index 141aebea..f6cbbc1a 100644
--- i/internal/status/types.go
+++ w/internal/status/types.go
@@ -23,6 +23,17 @@ const (
 	StatusWarning StatusType = "WARNING"
 )

+// ErrorStage says where a failed check broke, when the check can tell. The
+// zero value means unspecified: the failure is the target's own (an unreachable
+// host, a certificate error), as it was before checks could cross a proxy.
+type ErrorStage string
+
+const (
+	// StageProxy marks a failure of the proxy step: the proxy could not be
+	// reached, refused CONNECT, did not answer, or is not supported.
+	StageProxy ErrorStage = "proxy"
+)
+
 // ComponentStatus represents a component's state
 type ComponentStatus struct {
 	Name         string
@@ -31,6 +42,7 @@ type ComponentStatus struct {
 	Status       StatusType
 	ResponseTime time.Duration
 	Error        string
+	ErrorStage   ErrorStage // empty = unspecified
 	Timestamp    time.Time

 	// SSL-specific fields (optional, only populated for SSL type)
diff --git i/internal/ui/status/view.go w/internal/ui/status/view.go
index 7056f5c7..58aa18bf 100644
--- i/internal/ui/status/view.go
+++ w/internal/ui/status/view.go
@@ -122,7 +122,25 @@ func (m Model) status() sharedcomponents.Status {
 	if m.checking || m.firstCheck {
 		return sharedcomponents.Status{Text: "Checking components...", Activity: !m.quietCheck}
 	}
-	return sharedcomponents.Status{}
+	return m.certificateFailure()
+}
+
+// certificateFailure carries the selected certificate's failure (proxy, x509,
+// dial) at level Error, derived from the selection on every render so it
+// follows the cursor and has no timer (Rule 128). Only a DOWN row counts: the
+// expiry states stay carried by the columns. The Monitors tab is unchanged.
+func (m Model) certificateFailure() sharedcomponents.Status {
+	if m.activeTab != TabCertificates {
+		return sharedcomponents.Status{}
+	}
+	sel, ok := m.sslTable.Selected()
+	if !ok || sel.Status != status.StatusDown || sel.Error == "" {
+		return sharedcomponents.Status{}
+	}
+	return sharedcomponents.Status{
+		Text:  sel.Name + " " + theme.IconChevronRight + " " + sel.Error,
+		Level: sharedcomponents.LevelError,
+	}
 }

 // renderTabs renders the tab bar for monitors/certificates

1	package status
2	
3	import (
4		"bytes"
5		"context"
6		"crypto/ecdsa"
7		"crypto/elliptic"
8		"crypto/rand"
9		"crypto/sha256"
10		"crypto/tls"
11		"crypto/x509"
12		"crypto/x509/pkix"
13		"encoding/base64"
14		"encoding/hex"
15		"errors"
16		"fmt"
17		"io"
18		"log"
19		"math/big"
20		"net"
21		"net/http"
22		"net/http/httptest"
23		"net/url"
24		"os"
25		"os/exec"
26		"strings"
27		"sync"
28		"testing"
29		"time"
30	
31		"github.com/anthnel/devdesk/internal/config"
32		"github.com/anthnel/devdesk/internal/netproxy"
33		"github.com/anthnel/devdesk/internal/testutil/connectproxy"
34	)
35	
36	// DEVDESK-581: the SSL monitor opens its own TLS connection, so it must follow
37	// the same proxy path as the HTTPS monitor. These tests drive the package
38	// variables certDialer and certRootCAs; none of them runs in parallel.
39	//
40	// Everything that targets "example.com:443" is redirected by the proxy (or by
41	// an injected DialContext) to a local test server; nothing reaches the network.
42	
43	const (
44		// testIssuer is the CommonName of the generated certificate (self-signed,
45		// so also its issuer).
46		testIssuer = "DevDesk Test"
47	
48		// envHelper makes the test binary run TestSSLEnvironmentHelper for real.
49		envHelper = "STATUS_TEST_SSL_HELPER"
50		// envTarget is the target the helper fetches a chain from.
51		envTarget = "STATUS_TEST_SSL_TARGET"
52		// envServer is the address the helper's DialContext gives the target when
53		// it is dialed directly.
54		envServer = "STATUS_TEST_SSL_SERVER"
55		// envCert is the server certificate, DER in base64: the helper's roots.
56		envCert = "STATUS_TEST_SSL_CERT"
57	
58		// resultPrefix marks the helper's answer among the test binary's output.
59		resultPrefix = "RESULT "
60	)
61	
62	// newCertServer starts a TLS server whose self-signed certificate covers every
63	// name and address the tests use as a target, and returns it with a pool that
64	// trusts it. The certificate is valid for years, so a check reads it as OK.
65	func newCertServer(t *testing.T) (*httptest.Server, *x509.CertPool) {
66		t.Helper()
67		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
68		if err != nil {
69			t.Fatal(err)
70		}
71		tmpl := &x509.Certificate{
72			SerialNumber:          big.NewInt(581),
73			Subject:               pkix.Name{CommonName: testIssuer},
74			NotBefore:             time.Now().Add(-time.Hour),
75			NotAfter:              time.Now().AddDate(5, 0, 0),
76			KeyUsage:              x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
77			ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
78			BasicConstraintsValid: true,
79			IsCA:                  true,
80			DNSNames:              []string{"example.com", "a.corp.test", "localhost"},
81			IPAddresses:           []net.IP{net.ParseIP("127.0.0.1"), net.ParseIP("::1"), net.ParseIP("10.1.2.3")},
82		}
83		der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
84		if err != nil {
85			t.Fatal(err)
86		}
87		srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
88			_, _ = io.WriteString(w, "reached")
89		}))
90		srv.Config.ErrorLog = log.New(io.Discard, "", 0) // failed handshakes are on purpose
91		srv.TLS = &tls.Config{Certificates: []tls.Certificate{{Certificate: [][]byte{der}, PrivateKey: key}}}
92		srv.StartTLS()
93		t.Cleanup(srv.Close)
94	
95		pool := x509.NewCertPool()
96		pool.AddCert(srv.Certificate())
97		return srv, pool
98	}
99	
100	// fixed is a Selector that always answers u.
101	func fixed(u *url.URL) netproxy.Selector {
102		return func(*url.URL) (*url.URL, error) { return u, nil }
103	}
104	
105	// direct is a Selector that never uses a proxy.
106	func direct(*url.URL) (*url.URL, error) { return nil, nil }
107	
108	// useCertDialer swaps certDialer and certRootCAs for the test and restores
109	// them when it ends.
110	func useCertDialer(t *testing.T, d netproxy.Dialer, roots *x509.CertPool) {
111		t.Helper()
112		oldDialer, oldRoots := certDialer, certRootCAs
113		certDialer, certRootCAs = d, roots
114		t.Cleanup(func() { certDialer, certRootCAs = oldDialer, oldRoots })
115	}
116	
117	// routeTo is a Dialer.DialContext that sends the connection for any of names
118	// to addr and leaves other addresses alone.
119	func routeTo(addr string, names ...string) func(context.Context, string, string) (net.Conn, error) {
120		return func(ctx context.Context, network, a string) (net.Conn, error) {
121			for _, n := range names {
122				if a == n {
123					a = addr
124				}
125			}
126			return (&net.Dialer{}).DialContext(ctx, network, a)
127		}
128	}
129	
130	func sslComponent(target string) config.ComponentConfig {
131		return config.ComponentConfig{Name: "cert", Type: "ssl", Target: target}
132	}
133	
134	func testContext(t *testing.T, d time.Duration) context.Context {
135		t.Helper()
136		ctx, cancel := context.WithTimeout(context.Background(), d)
137		t.Cleanup(cancel)
138		return ctx
139	}
140	
141	func leafFingerprint(c *x509.Certificate) string {
142		sum := sha256.Sum256(c.Raw)
143		return hex.EncodeToString(sum[:])
144	}
145	
146	// captureTransport remembers the chain the server presented on each response,
147	// which is what the HTTPS monitor saw.
148	type captureTransport struct {
149		base http.RoundTripper
150	
151		mu     sync.Mutex
152		chains [][]*x509.Certificate
153	}
154	
155	func (c *captureTransport) RoundTrip(req *http.Request) (*http.Response, error) {
156		resp, err := c.base.RoundTrip(req)
157		if resp != nil && resp.TLS != nil {
158			c.mu.Lock()
159			c.chains = append(c.chains, resp.TLS.PeerCertificates)
160			c.mu.Unlock()
161		}
162		return resp, err
163	}
164	
165	func (c *captureTransport) seen() [][]*x509.Certificate {
166		c.mu.Lock()
167		defer c.mu.Unlock()
168		return append([][]*x509.Certificate(nil), c.chains...)
169	}
170	
171	func TestSSLDefaultsFollowTheEnvironment(t *testing.T) {
172		// The zero Dialer reads the proxy variables, and nothing pins the roots:
173		// without a proxy variable the monitor behaves as it always did.
174		if certDialer.Proxy != nil || certDialer.DialContext != nil || certDialer.ProxyTLSConfig != nil {
175			t.Errorf("certDialer = %+v, want the zero netproxy.Dialer", certDialer)
176		}
177		if certRootCAs != nil {
178			t.Error("certRootCAs is set, want nil (system roots)")
179		}
180	}
181	
182	func TestSSLCheckerThroughProxyMatchesTheHTTPSMonitor(t *testing.T) {
183		srv, pool := newCertServer(t)
184		proxy := connectproxy.Start(t, connectproxy.Options{
185			Route: func(string) string { return srv.Listener.Addr().String() },
186		})
187		sel := fixed(proxy.URL())
188		useCertDialer(t, netproxy.Dialer{Proxy: sel}, pool)
189	
190		// The HTTPS monitor, through the same proxy and the same trust.
191		tr := netproxy.NewTransport(sel)
192		tr.TLSClientConfig = &tls.Config{RootCAs: pool}
193		t.Cleanup(tr.CloseIdleConnections)
194		capture := &captureTransport{base: tr}
195		httpChecker := NewHTTPChecker(5 * time.Second)
196		httpChecker.client.Transport = capture
197	
198		ctx := testContext(t, 20*time.Second)
199		httpRes := httpChecker.Check(ctx, config.ComponentConfig{Name: "web", Type: "https", Target: "example.com"})
200		if httpRes.Status != StatusOK {
201			t.Fatalf("HTTPS monitor = %s (%s), want OK", httpRes.Status, httpRes.Error)
202		}
203		chains := capture.seen()
204		if len(chains) != 1 || len(chains[0]) == 0 {
205			t.Fatalf("the HTTPS monitor saw %d chains, want 1 with a leaf", len(chains))
206		}
207		leaf := chains[0][0]
208	
209		res := NewSSLChecker(5*time.Second).Check(ctx, sslComponent("example.com"))
210		if res.Status != StatusOK {
211			t.Fatalf("SSL monitor = %s (%s), want OK", res.Status, res.Error)
212		}
213		if res.ErrorStage != "" {
214			t.Errorf("ErrorStage = %q on a success, want empty", res.ErrorStage)
215		}
216		if res.SSLExpires == nil || !res.SSLExpires.Equal(leaf.NotAfter) {
217			t.Errorf("SSLExpires = %v, want the HTTPS monitor's %v", res.SSLExpires, leaf.NotAfter)
218		}
219		if res.SSLIssuer != leaf.Issuer.CommonName || res.SSLIssuer != testIssuer {
220			t.Errorf("SSLIssuer = %q, want %q (the HTTPS monitor's %q)", res.SSLIssuer, testIssuer, leaf.Issuer.CommonName)
221		}
222		wantDays := int(time.Until(leaf.NotAfter).Hours() / 24)
223		if res.SSLDaysLeft == nil || *res.SSLDaysLeft < wantDays-1 || *res.SSLDaysLeft > wantDays+1 {
224			t.Errorf("SSLDaysLeft = %v, want about %d", res.SSLDaysLeft, wantDays)
225		}
226	
227		// Both monitors went through the proxy, to the same target.
228		reqs := proxy.Requests()
229		if len(reqs) != 2 {
230			t.Fatalf("proxy received %d CONNECTs, want 2 (one per monitor): %+v", len(reqs), reqs)
231		}
232		for _, r := range reqs {
233			if r.Target != "example.com:443" {
234				t.Errorf("CONNECT target = %q, want example.com:443", r.Target)
235			}
236		}
237	}
238	
239	func TestSSLFetchChainThroughProxyReturnsTheServerChain(t *testing.T) {
240		srv, pool := newCertServer(t)
241		proxy := connectproxy.Start(t, connectproxy.Options{
242			Route: func(string) string { return srv.Listener.Addr().String() },
243		})
244		useCertDialer(t, netproxy.Dialer{Proxy: fixed(proxy.URL())}, pool)
245	
246		chain, err := FetchCertificateChainContext(testContext(t, 20*time.Second), "example.com", 5*time.Second)
247		if err != nil {
248			t.Fatalf("FetchCertificateChainContext: %v", err)
249		}
250		if len(chain) == 0 || leafFingerprint(chain[0]) != leafFingerprint(srv.Certificate()) {
251			t.Fatalf("chain = %d certificates, leaf not the server's", len(chain))
252		}
253		reqs := proxy.Requests()
254		if len(reqs) != 1 || reqs[0].Target != "example.com:443" {
255			t.Fatalf("CONNECTs = %+v, want one to example.com:443 (a bare target defaults to :443)", reqs)
256		}
257	}
258	
259	func TestSSLCheckerProxyRefusal(t *testing.T) {
260		tests := []struct {
261			name string
262			code int
263			want string
264		}{
265			{"forbidden", http.StatusForbidden, "proxy: CONNECT refused (403"},
266			{"proxy authentication required", http.StatusProxyAuthRequired, "proxy: CONNECT refused (407"},
267		}
268		for _, tt := range tests {
269			t.Run(tt.name, func(t *testing.T) {
270				_, pool := newCertServer(t)
271				proxy := connectproxy.Start(t, connectproxy.Options{Refuse: tt.code})
272				useCertDialer(t, netproxy.Dialer{Proxy: fixed(proxy.URL())}, pool)
273	
