18	// maxConnectAnswer caps what is read while waiting for the answer to CONNECT: a
19	// proxy that never ends its header cannot make the check buffer without bound.
20	const maxConnectAnswer = 64 << 10
21	
22	// Dialer opens TLS connections along the path an https request would take. The
23	// zero value follows the proxy environment variables.
24	type Dialer struct {
25		// Proxy picks the proxy; nil means FromEnvironment.
26		Proxy Selector
27		// DialContext opens the TCP connection (to the proxy, or to the target when
28		// direct); nil means (&net.Dialer{}).DialContext.
29		DialContext func(ctx context.Context, network, addr string) (net.Conn, error)
30		// ProxyTLSConfig configures TLS to an https:// proxy; nil means system roots.
31		ProxyTLSConfig *tls.Config
32	}
33	
34	// DialTLS connects to hostport (the port is required) the way an https request
35	// to it would travel, then completes the handshake with cfg (ServerName
36	// defaults to the host). ctx bounds the whole: proxy dial, CONNECT, handshake.
37	//
38	// A failure of the proxy step is a *Error; a failure of the target itself (its
39	// handshake, its certificate) is returned as it would be without a proxy. The
40	// returned connection owns the tunnel: closing it closes the socket.
41	func (d Dialer) DialTLS(ctx context.Context, hostport string, cfg *tls.Config) (*tls.Conn, error) {
42		if err := checkTarget(hostport); err != nil {
43			return nil, err
44		}
45		host, _, err := net.SplitHostPort(hostport)
46		if err != nil {
47			return nil, err
48		}
49		sel := d.Proxy
50		if sel == nil {
51			sel = FromEnvironment
52		}
53		proxy, err := sel(&url.URL{Scheme: "https", Host: hostport})
54		if err != nil {
55			return nil, &Error{Step: StepSelect, Err: err}
56		}
57		if proxy != nil && proxy.Scheme != "http" && proxy.Scheme != "https" {
58			return nil, &Error{Proxy: proxy.Host, Step: StepScheme, Err: errors.New(proxy.Scheme)}
59		}
60	
61		conn, err := d.tunnel(ctx, proxy, hostport)
62		if err != nil {
63			return nil, err
64		}
65	
66		tc := tls.Client(conn, targetConfig(cfg, host))
67		if err := tc.HandshakeContext(ctx); err != nil {
68			_ = conn.Close()
69			return nil, err
70		}
71		_ = conn.SetDeadline(time.Time{})
72		return tc, nil
73	}
74	
75	// checkTarget refuses a hostport holding a byte at or below space, or DEL: the
76	// target is written into the CONNECT line and its Host header, where a CR or LF
77	// would end the line and inject a header and a space would split the authority.
78	// It runs before anything else, so nothing is dialed and no selector is asked.
79	// The error quotes the value (%q), never raw.
80	func checkTarget(hostport string) error {
81		for i := 0; i < len(hostport); i++ {
82			if c := hostport[i]; c <= 0x20 || c == 0x7f {
83				return fmt.Errorf("netproxy: invalid target %q: control character or space at offset %d", hostport, i)
84			}
85		}
86		return nil
87	}
88	
89	// tunnel returns a connection to hostport: direct when proxy is nil, otherwise
90	// through proxy by CONNECT. One deadline, ctx's, covers every step; on failure
91	// the connection is closed. The deadline is left set so the caller's handshake
92	// stays under it.
93	func (d Dialer) tunnel(ctx context.Context, proxy *url.URL, hostport string) (net.Conn, error) {
94		dial := d.DialContext
95		if dial == nil {
96			dial = (&net.Dialer{}).DialContext
97		}
98		if proxy == nil {
99			conn, err := dial(ctx, "tcp", hostport)
100			if err != nil {
101				return nil, err
102			}
103			if dl, ok := ctx.Deadline(); ok {
104				_ = conn.SetDeadline(dl)
105			}
106			return conn, nil
107		}
108	
109		addr := proxyAddr(proxy)
110		raw, err := dial(ctx, "tcp", addr)
111		if err != nil {
112			return nil, &Error{Proxy: addr, Step: StepDial, Err: err}
113		}
114		if dl, ok := ctx.Deadline(); ok {
115			_ = raw.SetDeadline(dl)
116		}
117		// A cancellation unblocks the reads and writes below by closing the socket.
118		stop := context.AfterFunc(ctx, func() { _ = raw.Close() })
119		conn, perr := d.connect(ctx, raw, proxy, addr, hostport)
120		if perr != nil {
121			stop()
122			return nil, perr
123		}
124		if !stop() {
125			// The cancellation fired after the CONNECT succeeded: the socket is closed.
126			_ = conn.Close()
127			return nil, &Error{Proxy: addr, Step: StepConnect, Err: ctx.Err()}
128		}
129		return conn, nil
130	}
131	
132	// connect runs TLS to the proxy when it is https://, then the CONNECT exchange,
133	// on conn. It closes conn on failure.
134	func (d Dialer) connect(ctx context.Context, conn net.Conn, proxy *url.URL, addr, hostport string) (net.Conn, *Error) {
135		fail := func(step Step, status int, err error) (net.Conn, *Error) {
136			_ = conn.Close()
137			if errors.Is(err, net.ErrClosed) && ctx.Err() != nil {
138				err = ctx.Err() // our own AfterFunc closed it: the cause is the context's
139			}
140			return nil, &Error{Proxy: addr, Step: step, StatusCode: status, Err: err}
141		}
142	
143		if proxy.Scheme == "https" {
144			cfg := &tls.Config{}
145			if d.ProxyTLSConfig != nil {
146				cfg = d.ProxyTLSConfig.Clone()
147			}
148			if cfg.ServerName == "" {
149				cfg.ServerName = proxy.Hostname()
150			}
151			tc := tls.Client(conn, cfg)
152			if err := tc.HandshakeContext(ctx); err != nil {
153				return fail(StepProxyTLS, 0, err)
154			}
155			conn = tc
156		}
157	
158		if _, err := io.WriteString(conn, connectRequest(proxy.User, hostport)); err != nil {
159			return fail(StepConnect, 0, err)
160		}
161		br := bufio.NewReader(io.LimitReader(conn, maxConnectAnswer))
162		resp, err := http.ReadResponse(br, &http.Request{Method: http.MethodConnect})
163		if err != nil {
164			return fail(StepConnect, 0, err)
165		}
166		// The body of a CONNECT answer is the tunnel; it is not read or closed here.
167		if resp.StatusCode != http.StatusOK {
168			return fail(StepConnect, resp.StatusCode, nil)
169		}
170		if n := br.Buffered(); n > 0 {
171			// Bytes read past the header belong to the tunnel; give them back first.
172			peeked, _ := br.Peek(n)
173			return &bufferedConn{Conn: conn, r: io.MultiReader(bytes.NewReader(bytes.Clone(peeked)), conn)}, nil
174		}
175		return conn, nil
176	}
177	
178	// bufferedConn is a net.Conn whose reads start with bytes already taken off it.
179	type bufferedConn struct {
180		net.Conn
181		r io.Reader
182	}
183	
184	func (c *bufferedConn) Read(p []byte) (int, error) { return c.r.Read(p) }
185	
186	// connectRequest is the CONNECT request for hostport, with Basic credentials
187	// from user when the proxy URL carries any.
188	func connectRequest(user *url.Userinfo, hostport string) string {
189		req := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n", hostport, hostport)
190		if user != nil {
191			password, _ := user.Password()
192			cred := base64.StdEncoding.EncodeToString([]byte(user.Username() + ":" + password))
193			req += "Proxy-Authorization: Basic " + cred + "\r\n"
194		}
195		return req + "\r\n"
196	}
197	
198	// proxyAddr is the proxy's host:port, without userinfo, with the scheme's
199	// default port when the URL has none.
200	func proxyAddr(proxy *url.URL) string {
201		if proxy.Port() != "" {
202			return proxy.Host
203		}
204		port := "80"
205		if proxy.Scheme == "https" {
206			port = "443"
207		}
208		return net.JoinHostPort(proxy.Hostname(), port)
209	}
210	
211	// targetConfig is a copy of cfg (or a fresh config) that verifies host unless
212	// cfg names another server.
213	func targetConfig(cfg *tls.Config, host string) *tls.Config {
214		c := &tls.Config{}
215		if cfg != nil {
216			c = cfg.Clone()
217		}
218		if c.ServerName == "" {
219			c.ServerName = host
220		}
221		return c
222	}
